<?php require_once __DIR__.'/../includes/auth.php'; require_role(['student']); $pageTitle='My Reports'; require __DIR__.'/../includes/header.php'; $s=$pdo->prepare('SELECT r.*,c.name category FROM item_reports r JOIN categories c ON c.id=r.category_id WHERE r.user_id=? ORDER BY r.created_at DESC');$s->execute([current_user()['id']]);$rows=$s->fetchAll();echo '<h1>My reports</h1><div class="table-wrap"><table><tr><th>Item</th><th>Type</th><th>Status</th><th>Created</th></tr>';foreach($rows as $r){echo '<tr><td>'.e($r['item_name']).'</td><td>'.e($r['report_type']).'</td><td>'.e($r['status']).'</td><td>'.e($r['created_at']).'</td></tr>';}echo '</table></div>'; require __DIR__.'/../includes/footer.php'; ?>